import{_ as l,B as i,o as s,c,a8 as d,a,E as t,f as n}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse('{"title":"File manager (executable)","description":"The file manager executable provides a graphical VFS browser with directory navigation controls.","frontmatter":{"layout":"doc","docType":"explanation","description":"The file manager executable provides a graphical VFS browser with directory navigation controls."},"headers":[],"relativePath":"explanation/architecture/executables/file_manager.md","filePath":"explanation/architecture/executables/file_manager.md","lastUpdated":1793145952000}'),u={name:"explanation/architecture/executables/file_manager.md"};function h(p,e,m,g,f,b){const r=i("CodeReference"),o=i("HostReference");return s(),c("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[4]||(e[4]=d('<h1 id="file-manager-executable" tabindex="-1">File manager (executable) <a class="header-anchor" href="#file-manager-executable" aria-label="Permalink to &quot;File manager (executable)&quot;">​</a></h1><p>The file manager executable provides a graphical VFS browser with directory navigation controls.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><ul><li>Presents VFS directory contents in a graphical list view.</li><li>Handles path navigation (home/up/go/refresh) and directory item traversal.</li><li>Registers launcher shortcut metadata for shell discovery.</li></ul><h2 id="startup-and-lifecycle" tabindex="-1">Startup and lifecycle <a class="header-anchor" href="#startup-and-lifecycle" aria-label="Permalink to &quot;Startup and lifecycle&quot;">​</a></h2><ol><li>Installation path writes <code>/configuration/shared/shortcuts/file_manager.json</code>.</li><li>Runtime path creates window, toolbar, path text area, and file list widgets.</li><li>Loads current directory entries, sorts directories-first, and renders list buttons.</li><li>Processes click/close events in loop until window close.</li></ol><h2 id="runtime-integration-points" tabindex="-1">Runtime integration points <a class="header-anchor" href="#runtime-integration-points" aria-label="Permalink to &quot;Runtime integration points&quot;">​</a></h2><ul><li>Graphics/LVGL for window/list/event handling.</li><li><code>virtual_file_system::Directory</code> for directory iteration.</li><li>Task manager for current task identifier during VFS operations.</li></ul><h2 id="data-and-control-flow-vfs-touchpoints" tabindex="-1">Data and control flow / VFS touchpoints <a class="header-anchor" href="#data-and-control-flow-vfs-touchpoints" aria-label="Permalink to &quot;Data and control flow / VFS touchpoints&quot;">​</a></h2><ul><li>Core VFS touchpoint: <code>Directory::open(..., current_path)</code> + iterative <code>read()</code>.</li><li>Navigation updates <code>current_path</code>, then refreshes UI from VFS.</li><li>File entries are transformed into in-memory <code>FileItem</code> records before rendering.</li></ul><h2 id="concurrency-and-event-loop-model" tabindex="-1">Concurrency and event-loop model <a class="header-anchor" href="#concurrency-and-event-loop-model" aria-label="Permalink to &quot;Concurrency and event-loop model&quot;">​</a></h2><ul><li>The top-level event loop <strong>does not poll every 50 ms</strong>. <code>FileManager::handle_events()</code> drains events under the graphics lock, registers the window&#39;s waker with <code>task::suspend</code>, and wakes when the window signals new activity.</li><li>Event handlers run asynchronously and mutate local state; there are no separately spawned application worker tasks. Graphics and VFS remain independently scheduled.</li></ul><h2 id="failure-semantics" tabindex="-1">Failure semantics <a class="header-anchor" href="#failure-semantics" aria-label="Permalink to &quot;Failure semantics&quot;">​</a></h2><ul><li>UI creation failures return typed <code>Error</code> and abort startup.</li><li>During event handling, directory-read and invalid-path errors are <strong>logged and the event loop continues</strong>, rather than automatically ending the executable.</li><li>Invalid path text input logs error and retains current path.</li></ul><h2 id="contract-vs-implementation" tabindex="-1">Contract vs implementation <a class="header-anchor" href="#contract-vs-implementation" aria-label="Permalink to &quot;Contract vs implementation&quot;">​</a></h2><ul><li><strong>Contract</strong>: graphical executable that reflects directory state and reacts to navigation events.</li><li><strong>Current implementation</strong>: LVGL list-based browser with direct directory-only navigation and no file-open dispatch path.</li></ul><h2 id="operational-limitations" tabindex="-1">Operational limitations <a class="header-anchor" href="#operational-limitations" aria-label="Permalink to &quot;Operational limitations&quot;">​</a></h2><ul><li>Operations are currently browse-oriented; edit/copy/move/delete workflows are not implemented in top-level flow.</li><li>Path input accepts raw text and relies on <code>PathOwned</code> validation.</li></ul><h2 id="exact-api-input-handling-and-ownership" tabindex="-1">Exact API, input handling and ownership <a class="header-anchor" href="#exact-api-input-handling-and-ownership" aria-label="Permalink to &quot;Exact API, input handling and ownership&quot;">​</a></h2><p><code>FileManagerExecutable::new(vfs, task)</code> registers a desktop shortcut in <code>/configuration/shared/shortcuts/file_manager.json</code> using <code>application_metadata::shortcut(&quot;file_manager&quot;)</code>. Launch uses the shared <code>ExecutableTrait</code> contract and a <code>&#39;static ExecutableContext</code>; it creates an <code>OwnedWindow</code> with a toolbar, path text area and LVGL list.</p><p><code>FileManager::new(context).await</code> begins at <code>PathOwned::root()</code> (<code>/</code>). <code>load_directory</code> opens the current directory with the current task identifier, iterates VFS entries, skips <code>.</code> and <code>..</code>, and sorts <strong>directories first</strong>, with names in ascending lexicographic order in each group. A <code>FileItem</code> contains name, kind and size. Navigation is handled through Home, Up, Refresh, Go and directory-item clicks.</p><p><code>handle_events().await -&gt; bool</code> returns false after a close/delete event on the owning window; while waiting, it registers a <strong>window waker</strong>, avoiding a busy-polling UI loop. The event handler logs recoverable errors rather than terminating the process.</p><p>The application navigates directories and displays file metadata; it does <strong>not</strong> currently open arbitrary documents in another program or expose copy/move/delete commands. LVGL object pointers are owned by the current window and must only be manipulated under the Graphics lock.</p><h3 id="source-and-api-references" tabindex="-1">Source and API references <a class="header-anchor" href="#source-and-api-references" aria-label="Permalink to &quot;Source and API references&quot;">​</a></h3>',24)),a("ul",null,[a("li",null,[t(r,{repo:"applications",path:"executables/file_manager/src/lib.rs"}),e[0]||(e[0]=n(" — executable registration and launch.",-1))]),a("li",null,[t(r,{repo:"applications",path:"executables/file_manager/src/file_manager.rs"}),e[1]||(e[1]=n(" — navigation, sorting, event wake-up and UI.",-1))]),a("li",null,[t(o,{repo:"applications",crate:"file_manager"}),e[2]||(e[2]=n(" — native Rust API.",-1))])]),e[5]||(e[5]=a("h2",{id:"references",tabindex:"-1"},[n("References "),a("a",{class:"header-anchor",href:"#references","aria-label":'Permalink to "References"'},"​")],-1)),a("ul",null,[a("li",null,[t(r,{repo:"applications",path:"executables/file_manager"})]),e[3]||(e[3]=a("li",null,[a("a",{href:"/explanation/architecture/subsystems/virtual_file_system.html"},"Virtual file system")],-1))])])}const x=l(u,[["render",h]]);export{v as __pageData,x as default};
